<script setup lang="ts">
import type {IssueDto,PhotoUploadDto} from '~/types/api'
import {errorMessage,todayLocal} from '~/utils/format'
const props=defineProps<{issue:IssueDto}>(),emit=defineEmits<{saved:[]}>()
const open=ref(false),busy=ref(false),uploading=ref(false),error=ref(''),kind=ref('progress'),date=ref(todayLocal()),notes=ref(''),deadline=ref(''),unit=ref(''),follower=ref(''),photos=ref<PhotoUploadDto[]>([])
interface History{id:string;at:string;action:string;after:string}
const history=ref<History[]>([]), revision=ref(0), staff=ref<string[]>([])
const followerOptions=computed(()=>[...new Set([...staff.value,...(follower.value?[follower.value]:[])])])
onMounted(async()=>{try{staff.value=(await $fetch<{name:string}[]>('/api/records/staff')).map(x=>x.name)}catch(e){error.value=errorMessage(e)}})
const kinds=[{label:'跟进记录',value:'progress'},{label:'转交单位',value:'transfer'},{label:'延长期限',value:'extend'},{label:'安排跟进人',value:'assign'}]
function summary(item:History){try{const data=JSON.parse(item.after);return [data.date,data.notes,data.kind==='extend'?`新期限 ${data.deadline}`:'',data.kind==='transfer'?`转交 ${data.responsibleUnit}`:'',data.follower?`跟进人 ${data.follower}`:''].filter(Boolean).join(' · ')}catch{return item.after}}
async function load(){try{history.value=await $fetch(`/api/history/${props.issue.id}`)}catch(e){error.value=errorMessage(e)}}
async function save(){if(!notes.value.trim()){error.value='请填写办理说明';return}busy.value=true;error.value='';try{await $fetch(`/api/issues/${props.issue.id}/operations`,{method:'POST',body:{revision:revision.value,kind:kind.value,date:date.value,notes:notes.value,deadline:deadline.value,responsibleUnit:unit.value,follower:follower.value,photoIds:photos.value.map(x=>x.id)},retry:0});open.value=false;notes.value='';photos.value=[];await load();emit('saved')}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
watch(()=>props.issue.id,load,{immediate:true})
</script>
<template><div class="mt-3"><p v-if="issue.follower" class="text-sm mb-2">跟进人：{{issue.follower}}</p><UButton v-if="issue.status!=='closed'" label="跟进 / 转交 / 延期" color="neutral" variant="outline" @click="revision=issue.revision;follower=issue.follower??'';deadline=issue.deadline;unit=issue.responsibleUnit;open=true" /><div v-for="item in history" :key="item.id" class="mt-3 border-l-2 border-default pl-3"><strong class="text-sm">{{item.action}}</strong><p class="text-sm text-muted">{{summary(item)}}</p></div><UModal v-model:open="open" title="登记办理情况" :dismissible="!busy&&!uploading"><template #body><div class="space-y-4"><UAlert v-if="error" :description="error" color="error" /><USelect v-model="kind" :items="kinds" class="w-full" /><UFormField label="办理日期"><UInput v-model="date" type="date" /></UFormField><UFormField v-if="kind==='extend'" label="新的期限" required><UInput v-model="deadline" type="date" /></UFormField><UFormField v-if="kind==='transfer'" label="接收单位" required><UInput v-model="unit" class="w-full" /></UFormField><UFormField label="社区跟进人员"><USelectMenu v-model="follower" :items="followerOptions" placeholder="选择人员" class="w-full" /></UFormField><UFormField label="办理说明" required><UTextarea v-model="notes" class="w-full" :rows="3" /></UFormField><UFormField label="现场照片"><PhotoUploader v-model="photos" phase="site" :disabled="busy" @busy="uploading=$event" /></UFormField></div></template><template #footer><UButton label="保存" :loading="busy" :disabled="uploading" @click="save" /></template></UModal></div></template>
